-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

create policy "senders create messages" on public.messages
  as permissive
  for insert
  to public
  with check ((( SELECT auth.uid() AS uid)) = sender_id AND (( SELECT auth.uid() AS uid)) IS DISTINCT FROM recipient_id AND (order_id IS NOT NULL AND (EXISTS ( SELECT 1
   FROM public.orders o
  WHERE o.id = messages.order_id AND ((( SELECT auth.uid() AS uid)) = o.buyer_id OR (( SELECT auth.uid() AS uid)) = o.seller_id) AND (messages.recipient_id = o.buyer_id OR messages.recipient_id = o.seller_id))) OR offer_id IS NOT NULL AND (EXISTS ( SELECT 1
   FROM public.offers f
     JOIN public.listings l ON l.id = f.listing_id
  WHERE f.id = messages.offer_id AND ((( SELECT auth.uid() AS uid)) = f.buyer_id OR (( SELECT auth.uid() AS uid)) = l.seller_id) AND (messages.recipient_id = f.buyer_id OR messages.recipient_id = l.seller_id))) OR order_id IS NULL AND offer_id IS NULL AND listing_id IS NOT NULL AND (EXISTS ( SELECT 1
   FROM public.listings l
  WHERE l.id = messages.listing_id AND (l.status = ANY (ARRAY['active'::text, 'sold'::text])) AND messages.recipient_id = l.seller_id)) OR order_id IS NULL AND offer_id IS NULL AND listing_id IS NOT NULL AND public.listing_enquiry_reply_allowed(listing_id, recipient_id)));
